/// CDP event: `Storage.indexedDBContentUpdated`
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct IndexedDBContentUpdatedEvent {
    /// Origin to update.
    pub origin: String,
    /// Storage key to update.
    #[serde(rename = "storageKey")]
    pub storage_key: String,
    /// Storage bucket to update.
    #[serde(rename = "bucketId")]
    pub bucket_id: String,
    /// Database to update.
    #[serde(rename = "databaseName")]
    pub database_name: String,
    /// ObjectStore to update.
    #[serde(rename = "objectStoreName")]
    pub object_store_name: String,
}

impl Event for IndexedDBContentUpdatedEvent {
    const METHOD: &'static str = "Storage.indexedDBContentUpdated";
}

